+// ContactForm — React-style component logic for standalone HTML
+
+const ContactForm = (() => {
+  // ── State ──────────────────────────────────────────────────────────────────
+  const state = {
+    fullName: { value: '', touched: false },
+    email:    { value: '', touched: false },
+    phone:    { value: '', touched: false },
+  };
+
+  // ── Validators ─────────────────────────────────────────────────────────────
+  const validators = {
+    fullName(value) {
+      if (!value.trim()) return 'Full name is required.';
+      if (value.trim().length < 2) return 'Please enter your full name.';
+      return null;
+    },
+    email(value) {
+      if (!value.trim()) return 'Email address is required.';
+      const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+      if (!re.test(value.trim())) return 'Please enter a valid email address.';
+      return null;
+    },
+    phone(value) {
+      if (!value.trim()) return null; // optional
+      // Allow formats: +1 (555) 000-0000 | 555-000-0000 | (555) 000-0000 | 5550000000
+      const re = /^(\+?1[\s.-]?)?(\(?\d{3}\)?[\s.-]?)[\d\s.-]{7,10}$/;
+      if (!re.test(value.trim())) return 'Please use format: (555) 000-0000 or +1 555-000-0000.';
+      return null;
+    },
+  };
+
+  // ── DOM helpers ────────────────────────────────────────────────────────────
+  function getInput(name)      { return document.getElementById(`field-${name}`); }
+  function getError(name)      { return document.getElementById(`error-${name}`); }
+
+  function renderField(name) {
+    const input = getInput(name);
+    const error = getError(name);
+    const field = state[name];
+
+    if (!field.touched) {
+      input.classList.remove('input-error', 'input-valid');
+      error.classList.remove('visible');
+      return;
+    }
+
+    const msg = validators[name](field.value);
+    if (msg) {
+      input.classList.add('input-error');
+      input.classList.remove('input-valid');
+      error.textContent = '';
+      // Rebuild with icon
+      error.innerHTML = `
+        <svg width="13" height="13" viewBox="0 0 16 16" fill="none" aria-hidden="true">
+          <circle cx="8" cy="8" r="7.5" stroke="#dc2626"/>
+          <path d="M8 4.5v4" stroke="#dc2626" stroke-width="1.5" stroke-linecap="round"/>
+          <circle cx="8" cy="11" r=".75" fill="#dc2626"/>
+        </svg>
+        ${msg}
+      `;
+      error.classList.add('visible');
+      input.setAttribute('aria-invalid', 'true');
+    } else {
+      input.classList.remove('input-error');
+      // Only mark valid if the user typed something (skip empty optional phone)
+      if (field.value.trim()) input.classList.add('input-valid');
+      else input.classList.remove('input-valid');
+      error.classList.remove('visible');
+      error.textContent = '';
+      input.removeAttribute('aria-invalid');
+    }
+  }
+
+  // ── Event wiring ───────────────────────────────────────────────────────────
+  function bindField(name) {
+    const input = getInput(name);
+
+    input.addEventListener('input', () => {
+      state[name].value = input.value;
+      if (state[name].touched) renderField(name);
+    });
+
+    input.addEventListener('blur', () => {
+      state[name].value = input.value;
+      state[name].touched = true;
+      renderField(name);
+    });
+  }
+
+  function handleSubmit(e) {
+    e.preventDefault();
+
+    // Mark all fields as touched and re-render
+    ['fullName', 'email', 'phone'].forEach(name => {
+      state[name].value = getInput(name).value;
+      state[name].touched = true;
+      renderField(name);
+    });
+
+    const hasErrors = ['fullName', 'email', 'phone'].some(
+      name => validators[name](state[name].value) !== null
+    );
+
+    if (hasErrors) {
+      // Focus first invalid input
+      const first = ['fullName', 'email', 'phone'].find(
+        name => validators[name](state[name].value) !== null
+      );
+      if (first) getInput(first).focus();
+      return;
+    }
+
+    // ── Success ──────────────────────────────────────────────────────────────
+    const banner = document.getElementById('success-banner');
+    banner.classList.add('visible');
+    banner.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
+
+    // Reset form
+    document.getElementById('contact-form').reset();
+    ['fullName', 'email', 'phone'].forEach(name => {
+      state[name] = { value: '', touched: false };
+      renderField(name);
+    });
+
+    // Hide banner after 5 s
+    setTimeout(() => banner.classList.remove('visible'), 5000);
+  }
+
+  // ── Init ───────────────────────────────────────────────────────────────────
+  function init() {
+    ['fullName', 'email', 'phone'].forEach(bindField);
+    document.getElementById('contact-form').addEventListener('submit', handleSubmit);
+  }
+
+  return { init };
+})();
+
+document.addEventListener('DOMContentLoaded', ContactForm.init);
+
')
